using System.Windows;
using System.Windows.Markup;
namespace JingYue {
 public static class UiTheme {
  public static void Install(ResourceDictionary resources){const string xaml=@"<ResourceDictionary xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' xmlns:sys='clr-namespace:System;assembly=mscorlib'>
  <Style TargetType='{x:Type TextBox}'>
   <Setter Property='Background' Value='{DynamicResource SearchFill}'/><Setter Property='Foreground' Value='{DynamicResource Ink}'/><Setter Property='BorderBrush' Value='{DynamicResource Accent}'/><Setter Property='CaretBrush' Value='{DynamicResource Accent}'/>
   <Setter Property='SelectionBrush' Value='{DynamicResource Accent}'/><Setter Property='SelectionOpacity' Value='0.3'/><Setter Property='Padding' Value='13,10'/><Setter Property='VerticalContentAlignment' Value='Center'/>
   <Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type TextBox}'><Border x:Name='Frame' CornerRadius='12' BorderThickness='1.25' BorderBrush='{TemplateBinding BorderBrush}' Background='{TemplateBinding Background}'><Grid><TextBlock x:Name='Hint' Visibility='Collapsed' Text='{TemplateBinding Tag}' Foreground='{DynamicResource Muted}' Margin='{TemplateBinding Padding}' VerticalAlignment='Center' IsHitTestVisible='False'/><ScrollViewer x:Name='PART_ContentHost' Margin='{TemplateBinding Padding}'/></Grid></Border><ControlTemplate.Triggers><Trigger Property='Text' Value=''><Setter TargetName='Hint' Property='Visibility' Value='Visible'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='Frame' Property='BorderThickness' Value='2'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style x:Key='ScrollSpace' TargetType='{x:Type RepeatButton}'><Setter Property='Focusable' Value='False'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type RepeatButton}'><Border Background='Transparent'/></ControlTemplate></Setter.Value></Setter></Style>
  <Style x:Key='ScrollHandle' TargetType='{x:Type Thumb}'><Setter Property='MinHeight' Value='30'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='{x:Type Thumb}'><Border x:Name='Pill' CornerRadius='6' Background='{DynamicResource ScrollThumb}' Margin='4,2'/><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='Pill' Property='Background' Value='{DynamicResource Accent}'/></Trigger><Trigger Property='IsDragging' Value='True'><Setter TargetName='Pill' Property='Background' Value='{DynamicResource Accent}'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  <ControlTemplate x:Key='VerticalRail' TargetType='{x:Type ScrollBar}'><Grid Background='Transparent'><Border Width='2' Margin='0,5' CornerRadius='1' HorizontalAlignment='Center' Background='{DynamicResource Line}'/><Track x:Name='PART_Track' IsDirectionReversed='True' Orientation='Vertical' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{TemplateBinding Value}' ViewportSize='{TemplateBinding ViewportSize}'><Track.DecreaseRepeatButton><RepeatButton Style='{StaticResource ScrollSpace}' Command='{x:Static ScrollBar.PageUpCommand}'/></Track.DecreaseRepeatButton><Track.Thumb><Thumb Style='{StaticResource ScrollHandle}'/></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Style='{StaticResource ScrollSpace}' Command='{x:Static ScrollBar.PageDownCommand}'/></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate>
  <ControlTemplate x:Key='HorizontalRail' TargetType='{x:Type ScrollBar}'><Grid Background='Transparent'><Border Height='2' Margin='5,0' CornerRadius='1' VerticalAlignment='Center' Background='{DynamicResource Line}'/><Track x:Name='PART_Track' Orientation='Horizontal' Minimum='{TemplateBinding Minimum}' Maximum='{TemplateBinding Maximum}' Value='{TemplateBinding Value}' ViewportSize='{TemplateBinding ViewportSize}'><Track.DecreaseRepeatButton><RepeatButton Style='{StaticResource ScrollSpace}' Command='{x:Static ScrollBar.PageLeftCommand}'/></Track.DecreaseRepeatButton><Track.Thumb><Thumb MinWidth='30'><Thumb.Template><ControlTemplate TargetType='{x:Type Thumb}'><Border CornerRadius='6' Background='{DynamicResource ScrollThumb}' Margin='2,4'/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb><Track.IncreaseRepeatButton><RepeatButton Style='{StaticResource ScrollSpace}' Command='{x:Static ScrollBar.PageRightCommand}'/></Track.IncreaseRepeatButton></Track></Grid></ControlTemplate>
  <Style TargetType='{x:Type ScrollBar}'><Style.Resources><sys:Double x:Key='{x:Static SystemParameters.VerticalScrollBarButtonHeightKey}'>64</sys:Double><sys:Double x:Key='{x:Static SystemParameters.HorizontalScrollBarButtonWidthKey}'>64</sys:Double></Style.Resources><Setter Property='Width' Value='16'/><Setter Property='Background' Value='Transparent'/><Setter Property='Template' Value='{StaticResource VerticalRail}'/><Style.Triggers><Trigger Property='Orientation' Value='Horizontal'><Setter Property='Width' Value='Auto'/><Setter Property='Height' Value='16'/><Setter Property='Template' Value='{StaticResource HorizontalRail}'/></Trigger></Style.Triggers></Style>
  </ResourceDictionary>";var dictionary=(ResourceDictionary)XamlReader.Parse(xaml);resources.MergedDictionaries.Add(dictionary);}
 }
}
